script:
(function () {
  'use strict';
  // Stock split adjustment. For a split of N new shares for every M old shares, factor = N / M:
  //   shares after = shares x factor (whole shares; any fraction is usually paid out as cash in lieu)
  //   price after  = price / factor; market value and total cost basis are unchanged
  //   cost basis per share after = total basis / (shares x factor)
  // Listed options (OCC convention, economically equivalent terms):
  //   whole-number forward split (2:1, 3:1, 10:1 ...): contracts x factor, strike / factor, 100 shares each
  //   any other ratio (3:2, reverse splits): contracts and strike unchanged, deliverable = 100 x factor shares
  // Verified: 100 shares at $150, 2-for-1 -> 200 shares at $75, $15,000 before and after; $12,000 basis
  // -> $120 then $60 per share; 1 call at $160 -> 2 calls at $80. 101 shares, 3-for-2 at $150 -> 151 shares
  // at $100 + $50 cash for 0.5 share. 1,000 shares at $2, 1-for-10 -> 100 shares at $20; 1 contract
  // -> 10 shares per contract, strike unchanged.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var price4 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 4 });
  var count = new Intl.NumberFormat('en-US', { maximumFractionDigits: 4 });

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function gcd(a, b) { while (b) { var t = b; b = a % b; a = t; } return a; }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function row(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (t, i) {
      var td = document.createElement(i === 0 ? 'th' : 'td');
      if (i === 0) td.setAttribute('scope', 'row');
      td.textContent = t;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  function split(shares, price, newN, oldN, basis) {
    var factor = newN / oldN;
    var exact = shares * factor;
    var wholeShares = Math.floor(exact + 1e-9);
    var fraction = Math.max(0, exact - wholeShares);
    if (fraction < 1e-9) fraction = 0;
    var newPrice = price / factor;
    return {
      factor: factor, exact: exact, whole: wholeShares, fraction: fraction, newPrice: newPrice,
      value: shares * price, cash: fraction * newPrice,
      basisBefore: basis / shares, basisAfter: basis / exact,
      basisFraction: basis * fraction / exact
    };
  }

  function adjustOption(contracts, strike, factor, wholeRatio) {
    if (wholeRatio && factor > 1) return { contracts: contracts * factor, strike: strike / factor, deliverable: 100 };
    return { contracts: contracts, strike: strike, deliverable: 100 * factor };
  }

  function update() {
    var shares = num('ssShares'), price = num('ssPrice'), newN = num('ssNew'), oldN = num('ssOld'),
        basis = num('ssBasis'), contracts = num('ssContracts'), strike = num('ssStrike');
    var useOptions = document.getElementById('ssHasOptions').checked;
    document.getElementById('ssOptionFields').hidden = !useOptions;
    var hasBasis = !isNaN(basis) && basis > 0;
    var error = document.getElementById('ssError');
    var msg = '';
    if ([shares, price, newN, oldN].some(isNaN)) msg = 'Enter the shares you own, the share price and both parts of the split ratio.';
    else if (shares <= 0 || price <= 0) msg = 'Shares and share price must be greater than zero.';
    else if (newN < 1 || oldN < 1 || newN % 1 !== 0 || oldN % 1 !== 0 || newN > 1000 || oldN > 1000) msg = 'Use whole numbers from 1 to 1,000 for the split ratio, such as 2 for 1 or 1 for 10.';
    else if (newN === oldN) msg = 'The two sides of the split ratio are equal, so nothing changes.';
    else if (!isNaN(basis) && basis < 0) msg = 'Cost basis cannot be negative.';
    else if (useOptions && (isNaN(contracts) || isNaN(strike) || contracts < 1 || contracts % 1 !== 0 || strike <= 0)) msg = 'Enter a whole number of option contracts and a strike price above zero.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var g = gcd(newN, oldN), n = newN / g, m = oldN / g;
    var r = split(shares, price, n, m, hasBasis ? basis : 0);
    var kind = n > m ? 'Forward split' : 'Reverse split';
    set('ssRatioLabel', kind + ': ' + n + ' new for every ' + m + ' old');
    set('ssNewShares', count.format(r.whole));
    set('ssNewPrice', price4.format(r.newPrice));
    set('ssValue', money.format(r.value));
    set('ssCash', r.fraction > 0 ? money.format(r.cash) + ' for ' + count.format(r.fraction) + ' share' : 'None');
    set('ssBasisAfter', hasBasis ? price4.format(r.basisAfter) : 'Enter cost basis');

    var body = document.getElementById('ssTable');
    while (body.firstChild) body.removeChild(body.firstChild);
    row(body, ['Shares', count.format(shares), count.format(r.exact) + (r.fraction > 0 ? ' (' + count.format(r.whole) + ' whole)' : '')]);
    row(body, ['Share price', price4.format(price), price4.format(r.newPrice)]);
    row(body, ['Market value', money.format(r.value), money.format(r.value)]);
    if (hasBasis) {
      row(body, ['Total cost basis', money.format(basis), money.format(basis)]);
      row(body, ['Cost basis per share', price4.format(r.basisBefore), price4.format(r.basisAfter)]);
      if (r.fraction > 0) row(body, ['Basis of the fractional share', '–', money.format(r.basisFraction)]);
    }
    if (useOptions) {
      var o = adjustOption(contracts, strike, n / m, m === 1);
      row(body, ['Option contracts', count.format(contracts), count.format(o.contracts)]);
      row(body, ['Strike price', price4.format(strike), price4.format(o.strike)]);
      row(body, ['Shares per contract', '100', count.format(o.deliverable)]);
      row(body, ['Shares controlled by options', count.format(contracts * 100), count.format(o.contracts * o.deliverable)]);
      set('ssOptionNote', m === 1
        ? 'Whole-number split: you get more contracts at a lower strike, each still covering 100 shares.'
        : (n > m ? 'Uneven split ratio' : 'Reverse split') + ': contracts and strike stay the same and each contract covers ' +
          count.format(o.deliverable) + ' shares. Check the exchange notice for exact terms and any cash.');
    } else {
      set('ssOptionNote', '');
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ssForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
